require_columns <- function(
  table_object,
  required_columns,
  source_name
) {
  missing_columns <- setdiff(
    required_columns,
    names(table_object)
  )

  if (length(missing_columns) > 0L) {
    stop(
      paste(
        "Missing required columns in",
        source_name,
        ":",
        paste(
          missing_columns,
          collapse = ", "
        )
      )
    )
  }

  invisible(TRUE)
}


coerce_logical_strict <- function(
  values,
  field_name
) {
  if (is.logical(values)) {
    if (anyNA(values)) {
      stop(
        paste(
          field_name,
          "contains missing logical values."
        )
      )
    }

    return(values)
  }

  normalized <- toupper(
    trimws(
      as.character(values)
    )
  )

  allowed_values <- c(
    "TRUE",
    "FALSE",
    "T",
    "F",
    "1",
    "0"
  )

  invalid <- (
    is.na(normalized) |
      !normalized %in%
        allowed_values
  )

  if (any(invalid)) {
    stop(
      paste(
        field_name,
        "contains values that cannot be interpreted as logical."
      )
    )
  }

  normalized %in% c(
    "TRUE",
    "T",
    "1"
  )
}


parse_semicolon_values <- function(value) {
  value <- as.character(value)

  if (
    length(value) == 0L ||
      is.na(value) ||
      !nzchar(trimws(value))
  ) {
    return(character())
  }

  values <- trimws(
    strsplit(
      value,
      ";",
      fixed = TRUE
    )[[1L]]
  )

  unique(
    values[nzchar(values)]
  )
}


normalize_expected_direction <- function(
  direction_value
) {
  value <- tolower(
    trimws(
      as.character(direction_value)
    )
  )

  bacterial_values <- c(
    "higher_in_bacterial",
    "bacterial_higher",
    "higher in bacterial",
    "bacterial-associated",
    "bacterial_associated"
  )

  viral_values <- c(
    "higher_in_viral",
    "viral_higher",
    "higher in viral",
    "viral-associated",
    "viral_associated"
  )

  if (value %in% bacterial_values) {
    return("higher_in_bacterial")
  }

  if (value %in% viral_values) {
    return("higher_in_viral")
  }

  if (
    grepl("bacter", value) &&
      grepl(
        "higher|associated",
        value
      )
  ) {
    return("higher_in_bacterial")
  }

  if (
    grepl("viral|virus", value) &&
      grepl(
        "higher|associated",
        value
      )
  ) {
    return("higher_in_viral")
  }

  stop(
    paste(
      "Unrecognized module direction:",
      direction_value
    )
  )
}


pairwise_difference_vector <- function(
  bacterial_scores,
  viral_scores
) {
  as.vector(
    outer(
      bacterial_scores,
      viral_scores,
      "-"
    )
  )
}


hodges_lehmann_shift <- function(
  bacterial_scores,
  viral_scores
) {
  median(
    pairwise_difference_vector(
      bacterial_scores,
      viral_scores
    )
  )
}


rank_biserial_from_pairwise <- function(
  bacterial_scores,
  viral_scores
) {
  differences <- pairwise_difference_vector(
    bacterial_scores,
    viral_scores
  )

  superiority_probability <- (
    sum(differences > 0) +
      0.5 * sum(differences == 0)
  ) / length(differences)

  2 * superiority_probability - 1
}


bootstrap_effect_sizes <- function(
  bacterial_scores,
  viral_scores,
  replicates,
  seed,
  ci_level,
  quantile_type
) {
  bacterial_n <- length(
    bacterial_scores
  )

  viral_n <- length(
    viral_scores
  )

  if (
    bacterial_n < 2L ||
      viral_n < 2L
  ) {
    stop(
      "Each bootstrap group must contain at least two observations."
    )
  }

  RNGkind(
    kind = "Mersenne-Twister",
    normal.kind = "Inversion",
    sample.kind = "Rejection"
  )

  set.seed(seed)

  hl_draws <- numeric(
    replicates
  )

  rank_biserial_draws <- numeric(
    replicates
  )

  for (bootstrap_index in seq_len(
    replicates
  )) {
    bacterial_bootstrap <- bacterial_scores[
      sample.int(
        bacterial_n,
        size = bacterial_n,
        replace = TRUE
      )
    ]

    viral_bootstrap <- viral_scores[
      sample.int(
        viral_n,
        size = viral_n,
        replace = TRUE
      )
    ]

    bootstrap_differences <- pairwise_difference_vector(
      bacterial_bootstrap,
      viral_bootstrap
    )

    hl_draws[bootstrap_index] <- median(
      bootstrap_differences
    )

    superiority_probability <- (
      sum(bootstrap_differences > 0) +
        0.5 *
          sum(bootstrap_differences == 0)
    ) / length(bootstrap_differences)

    rank_biserial_draws[bootstrap_index] <- (
      2 * superiority_probability - 1
    )
  }

  alpha <- 1 - ci_level

  probabilities <- c(
    alpha / 2,
    1 - alpha / 2
  )

  hl_interval <- as.numeric(
    quantile(
      hl_draws,
      probs = probabilities,
      names = FALSE,
      type = quantile_type,
      na.rm = TRUE
    )
  )

  rank_biserial_interval <- as.numeric(
    quantile(
      rank_biserial_draws,
      probs = probabilities,
      names = FALSE,
      type = quantile_type,
      na.rm = TRUE
    )
  )

  list(
    hl_ci_low =
      hl_interval[1L],
    hl_ci_high =
      hl_interval[2L],
    rank_biserial_ci_low =
      rank_biserial_interval[1L],
    rank_biserial_ci_high =
      rank_biserial_interval[2L],
    hl_bootstrap_mean =
      mean(hl_draws),
    hl_bootstrap_sd =
      sd(hl_draws),
    hl_bootstrap_minimum =
      min(hl_draws),
    hl_bootstrap_maximum =
      max(hl_draws),
    rank_biserial_bootstrap_mean =
      mean(rank_biserial_draws),
    rank_biserial_bootstrap_sd =
      sd(rank_biserial_draws),
    rank_biserial_bootstrap_minimum =
      min(rank_biserial_draws),
    rank_biserial_bootstrap_maximum =
      max(rank_biserial_draws),
    completed_replicates =
      length(hl_draws)
  )
}


confidence_interval_excludes_zero <- function(
  lower_bound,
  upper_bound
) {
  (
    lower_bound > 0 &&
      upper_bound > 0
  ) ||
    (
      lower_bound < 0 &&
        upper_bound < 0
    )
}


