# -------------------------------------------------------------------------
# Calculate effect sizes and bootstrap confidence intervals
# -------------------------------------------------------------------------

message(
  "Calculating effect sizes and 10,000-replicate confidence intervals..."
)

effect_rows <- vector(
  "list",
  expected_effect_rows
)

bootstrap_rows <- vector(
  "list",
  expected_effect_rows
)

result_index <- 0L

for (analysis_index in seq_len(
  nrow(analysis_manifest)
)) {
  current_manifest <- analysis_manifest[
    analysis_index
  ]

  analysis_id <- current_manifest$
    analysis_id

  representation_id <- current_manifest$
    scoring_representation

  bacterial_categories <- parse_semicolon_values(
    current_manifest$
      bacterial_categories
  )

  viral_categories <- parse_semicolon_values(
    current_manifest$
      viral_categories
  )

  expected_bacterial_n <- as.integer(
    current_manifest$
      bacterial_n
  )

  expected_viral_n <- as.integer(
    current_manifest$
      viral_n
  )

  analysis_scores <- scores[
    scoring_representation ==
      representation_id
  ]

  for (module_index in seq_along(
    expected_module_ids
  )) {
    result_index <- result_index + 1L

    module_id <- expected_module_ids[
      module_index
    ]

    message(
      paste0(
        "[",
        result_index,
        "/",
        expected_effect_rows,
        "] ",
        analysis_id,
        " / ",
        module_id
      )
    )

    module_scores <- analysis_scores[
      final_module_id ==
        module_id
    ]

    bacterial_scores <- module_scores[
      category %in%
        bacterial_categories,
      module_score
    ]

    viral_scores <- module_scores[
      category %in%
        viral_categories,
      module_score
    ]

    if (
      length(bacterial_scores) !=
        expected_bacterial_n ||
        length(viral_scores) !=
          expected_viral_n
    ) {
      stop(
        paste(
          "Unexpected group counts for",
          analysis_id,
          module_id,
          ": bacterial",
          length(bacterial_scores),
          "viral",
          length(viral_scores)
        )
      )
    }

    if (
      anyNA(bacterial_scores) ||
        anyNA(viral_scores) ||
        any(!is.finite(bacterial_scores)) ||
        any(!is.finite(viral_scores))
    ) {
      stop(
        paste(
          "Invalid scores detected for",
          analysis_id,
          module_id
        )
      )
    }

    expected_direction_raw <- module_scores$
      module_direction[1L]

    expected_direction <- normalize_expected_direction(
      expected_direction_raw
    )

    mean_bacterial <- mean(
      bacterial_scores
    )

    mean_viral <- mean(
      viral_scores
    )

    mean_difference <- (
      mean_bacterial -
        mean_viral
    )

    median_bacterial <- median(
      bacterial_scores
    )

    median_viral <- median(
      viral_scores
    )

    median_difference <- (
      median_bacterial -
        median_viral
    )

    hl_estimate <- hodges_lehmann_shift(
      bacterial_scores,
      viral_scores
    )

    wilcoxon_result <- suppressWarnings(
      wilcox.test(
        bacterial_scores,
        viral_scores,
        alternative = "two.sided",
        exact = FALSE
      )
    )

    wilcoxon_u <- as.numeric(
      wilcoxon_result$statistic
    )

    rank_biserial_from_u <- (
      2 * wilcoxon_u /
        (
          length(bacterial_scores) *
            length(viral_scores)
        )
    ) - 1

    rank_biserial_pairwise <- rank_biserial_from_pairwise(
      bacterial_scores,
      viral_scores
    )

    if (
      abs(
        rank_biserial_from_u -
          rank_biserial_pairwise
      ) >
        comparison_tolerance
    ) {
      stop(
        paste(
          "Rank-biserial implementations disagree for",
          analysis_id,
          module_id
        )
      )
    }

    observed_direction <- if (
      median_difference > 0
    ) {
      "higher_in_bacterial"
    } else if (
      median_difference < 0
    ) {
      "higher_in_viral"
    } else {
      "no_median_difference"
    }

    direction_retained <- (
      observed_direction ==
        expected_direction
    )

    bootstrap_seed <- (
      base_seed +
        analysis_index * 100L +
        module_index
    )

    bootstrap_result <- bootstrap_effect_sizes(
      bacterial_scores =
        bacterial_scores,
      viral_scores =
        viral_scores,
      replicates =
        bootstrap_replicates,
      seed =
        bootstrap_seed,
      ci_level =
        bootstrap_ci_level,
      quantile_type =
        bootstrap_quantile_type
    )

    hl_ci_excludes_zero <- confidence_interval_excludes_zero(
      bootstrap_result$hl_ci_low,
      bootstrap_result$hl_ci_high
    )

    rank_biserial_ci_excludes_zero <-
      confidence_interval_excludes_zero(
        bootstrap_result$
          rank_biserial_ci_low,
        bootstrap_result$
          rank_biserial_ci_high
      )

    effect_rows[[result_index]] <- data.table(
      analysis_id =
        analysis_id,
      analysis_role =
        current_manifest$
          analysis_role,
      scoring_representation =
        representation_id,
      z_reference_population =
        current_manifest$
          z_reference_population,
      bacterial_categories =
        current_manifest$
          bacterial_categories,
      viral_categories =
        current_manifest$
          viral_categories,
      final_module_id =
        module_id,
      final_module_label =
        module_scores$
          final_module_label[1L],
      expected_direction_raw =
        expected_direction_raw,
      expected_direction =
        expected_direction,
      observed_direction =
        observed_direction,
      direction_retained =
        direction_retained,
      bacterial_n =
        length(bacterial_scores),
      viral_n =
        length(viral_scores),
      mean_bacterial =
        mean_bacterial,
      mean_viral =
        mean_viral,
      mean_difference_bacterial_minus_viral =
        mean_difference,
      median_bacterial =
        median_bacterial,
      median_viral =
        median_viral,
      median_difference_bacterial_minus_viral =
        median_difference,
      hodges_lehmann_shift_bacterial_minus_viral =
        hl_estimate,
      hodges_lehmann_ci_low =
        bootstrap_result$
          hl_ci_low,
      hodges_lehmann_ci_high =
        bootstrap_result$
          hl_ci_high,
      hodges_lehmann_ci_excludes_zero =
        hl_ci_excludes_zero,
      wilcoxon_u =
        wilcoxon_u,
      rank_biserial_effect =
        rank_biserial_from_u,
      rank_biserial_ci_low =
        bootstrap_result$
          rank_biserial_ci_low,
      rank_biserial_ci_high =
        bootstrap_result$
          rank_biserial_ci_high,
      rank_biserial_ci_excludes_zero =
        rank_biserial_ci_excludes_zero,
      wilcoxon_p =
        wilcoxon_result$p.value,
      bootstrap_ci_method =
        paste0(
          "Stratified nonparametric percentile bootstrap; ",
          bootstrap_replicates,
          " replicates"
        ),
      bootstrap_ci_level =
        bootstrap_ci_level,
      bootstrap_quantile_type =
        bootstrap_quantile_type,
      bootstrap_seed =
        bootstrap_seed,
      bootstrap_replicates_completed =
        bootstrap_result$
          completed_replicates
    )

    bootstrap_rows[[result_index]] <- data.table(
      analysis_id =
        analysis_id,
      final_module_id =
        module_id,
      bacterial_n =
        length(bacterial_scores),
      viral_n =
        length(viral_scores),
      bootstrap_seed =
        bootstrap_seed,
      requested_replicates =
        bootstrap_replicates,
      completed_replicates =
        bootstrap_result$
          completed_replicates,
      ci_level =
        bootstrap_ci_level,
      quantile_type =
        bootstrap_quantile_type,
      hl_bootstrap_mean =
        bootstrap_result$
          hl_bootstrap_mean,
      hl_bootstrap_sd =
        bootstrap_result$
          hl_bootstrap_sd,
      hl_bootstrap_minimum =
        bootstrap_result$
          hl_bootstrap_minimum,
      hl_bootstrap_maximum =
        bootstrap_result$
          hl_bootstrap_maximum,
      rank_biserial_bootstrap_mean =
        bootstrap_result$
          rank_biserial_bootstrap_mean,
      rank_biserial_bootstrap_sd =
        bootstrap_result$
          rank_biserial_bootstrap_sd,
      rank_biserial_bootstrap_minimum =
        bootstrap_result$
          rank_biserial_bootstrap_minimum,
      rank_biserial_bootstrap_maximum =
        bootstrap_result$
          rank_biserial_bootstrap_maximum
    )
  }
}

effect_results <- rbindlist(
  effect_rows,
  use.names = TRUE,
  fill = TRUE
)

bootstrap_manifest <- rbindlist(
  bootstrap_rows,
  use.names = TRUE,
  fill = TRUE
)


# -------------------------------------------------------------------------
# Calculate within-analysis FDR
# -------------------------------------------------------------------------

effect_results[
  ,
  wilcoxon_q :=
    p.adjust(
      wilcoxon_p,
      method = "BH"
    ),
  by = analysis_id
]

effect_results[
  ,
  nominal_significant :=
    wilcoxon_p < 0.05
]

effect_results[
  ,
  fdr_significant :=
    wilcoxon_q < 0.05
]


# -------------------------------------------------------------------------
# Merge and compare against Script 47 reference results
# -------------------------------------------------------------------------

reference_comparison <- reference_tests[
  ,
  .(
    analysis_id,
    final_module_id,
    reference_bacterial_n =
      bacterial_n,
    reference_viral_n =
      viral_n,
    reference_mean_bacterial =
      mean_bacterial,
    reference_mean_viral =
      mean_viral,
    reference_mean_difference =
      mean_difference_bacterial_minus_viral,
    reference_median_bacterial =
      median_bacterial,
    reference_median_viral =
      median_viral,
    reference_median_difference =
      median_difference_bacterial_minus_viral,
    reference_wilcoxon_u =
      wilcoxon_u,
    reference_rank_biserial =
      rank_biserial_effect,
    reference_wilcoxon_p =
      wilcoxon_p,
    reference_wilcoxon_q =
      wilcoxon_q,
    reference_observed_direction =
      observed_direction,
    reference_direction_retained =
      direction_retained,
    reference_nominal_significant =
      nominal_significant,
    reference_fdr_significant =
      fdr_significant
  )
]

effect_results <- merge(
  effect_results,
  reference_comparison,
  by = c(
    "analysis_id",
    "final_module_id"
  ),
  all.x = TRUE,
  sort = FALSE
)

if (
  anyNA(
    effect_results$
      reference_bacterial_n
  )
) {
  stop(
    "The effect-size results did not merge completely with Script 47."
  )
}

effect_results[
  ,
  bacterial_n_matches_reference :=
    bacterial_n ==
      reference_bacterial_n
]

effect_results[
  ,
  viral_n_matches_reference :=
    viral_n ==
      reference_viral_n
]

effect_results[
  ,
  mean_bacterial_abs_difference :=
    abs(
      mean_bacterial -
        reference_mean_bacterial
    )
]

effect_results[
  ,
  mean_viral_abs_difference :=
    abs(
      mean_viral -
        reference_mean_viral
    )
]

effect_results[
  ,
  mean_difference_abs_difference :=
    abs(
      mean_difference_bacterial_minus_viral -
        reference_mean_difference
    )
]

effect_results[
  ,
  median_bacterial_abs_difference :=
    abs(
      median_bacterial -
        reference_median_bacterial
    )
]

effect_results[
  ,
  median_viral_abs_difference :=
    abs(
      median_viral -
        reference_median_viral
    )
]

effect_results[
  ,
  median_difference_abs_difference :=
    abs(
      median_difference_bacterial_minus_viral -
        reference_median_difference
    )
]

effect_results[
  ,
  wilcoxon_u_abs_difference :=
    abs(
      wilcoxon_u -
        reference_wilcoxon_u
    )
]

effect_results[
  ,
  rank_biserial_abs_difference :=
    abs(
      rank_biserial_effect -
        reference_rank_biserial
    )
]

effect_results[
  ,
  wilcoxon_p_abs_difference :=
    abs(
      wilcoxon_p -
        reference_wilcoxon_p
    )
]

effect_results[
  ,
  wilcoxon_q_abs_difference :=
    abs(
      wilcoxon_q -
        reference_wilcoxon_q
    )
]

effect_results[
  ,
  observed_direction_matches_reference :=
    observed_direction ==
      reference_observed_direction
]

effect_results[
  ,
  direction_retained_matches_reference :=
    direction_retained ==
      reference_direction_retained
]

effect_results[
  ,
  nominal_significance_matches_reference :=
    nominal_significant ==
      reference_nominal_significant
]

effect_results[
  ,
  fdr_significance_matches_reference :=
    fdr_significant ==
      reference_fdr_significant
]


# -------------------------------------------------------------------------
# Restore locked row order
# -------------------------------------------------------------------------

effect_results[
  ,
  analysis_order :=
    match(
      analysis_id,
      expected_analysis_ids
    )
]

effect_results[
  ,
  module_order :=
    match(
      final_module_id,
      expected_module_ids
    )
]

setorder(
  effect_results,
  analysis_order,
  module_order
)

effect_results[
  ,
  c(
    "analysis_order",
    "module_order"
  ) := NULL
]

bootstrap_manifest[
  ,
  analysis_order :=
    match(
      analysis_id,
      expected_analysis_ids
    )
]

bootstrap_manifest[
  ,
  module_order :=
    match(
      final_module_id,
      expected_module_ids
    )
]

setorder(
  bootstrap_manifest,
  analysis_order,
  module_order
)

bootstrap_manifest[
  ,
  c(
    "analysis_order",
    "module_order"
  ) := NULL
]


# -------------------------------------------------------------------------
# Manuscript-ready primary table
# -------------------------------------------------------------------------

primary_table <- effect_results[
  analysis_id ==
    "main_representative_all146_z_definite",
  .(
    final_module_id,
    final_module_label,
    expected_direction,
    bacterial_n,
    viral_n,
    median_bacterial,
    median_viral,
    median_difference_bacterial_minus_viral,
    hodges_lehmann_shift_bacterial_minus_viral,
    hodges_lehmann_ci_low,
    hodges_lehmann_ci_high,
    hodges_lehmann_ci_excludes_zero,
    rank_biserial_effect,
    rank_biserial_ci_low,
    rank_biserial_ci_high,
    rank_biserial_ci_excludes_zero,
    wilcoxon_p,
    wilcoxon_q,
    direction_retained,
    fdr_significant
  )
]


# -------------------------------------------------------------------------
# Analysis-level summary
# -------------------------------------------------------------------------

analysis_summary <- effect_results[
  ,
  .(
    module_count = .N,
    direction_retained_modules =
      sum(direction_retained),
    nominally_significant_modules =
      sum(nominal_significant),
    fdr_significant_modules =
      sum(fdr_significant),
    hodges_lehmann_ci_excluding_zero_modules =
      sum(
        hodges_lehmann_ci_excludes_zero
      ),
    rank_biserial_ci_excluding_zero_modules =
      sum(
        rank_biserial_ci_excludes_zero
      ),
    minimum_hodges_lehmann_shift =
      min(
        hodges_lehmann_shift_bacterial_minus_viral
      ),
    maximum_hodges_lehmann_shift =
      max(
        hodges_lehmann_shift_bacterial_minus_viral
      ),
    minimum_rank_biserial_effect =
      min(rank_biserial_effect),
    maximum_rank_biserial_effect =
      max(rank_biserial_effect)
  ),
  by = .(
    analysis_id,
    analysis_role,
    scoring_representation,
    z_reference_population
  )
]

analysis_summary[
  ,
  analysis_order :=
    match(
      analysis_id,
      expected_analysis_ids
    )
]

setorder(
  analysis_summary,
  analysis_order
)

analysis_summary[
  ,
  analysis_order := NULL
]


# -------------------------------------------------------------------------
# Quality gate
# -------------------------------------------------------------------------

effect_keys_unique <- !anyDuplicated(
  effect_results[
    ,
    .(
      analysis_id,
      final_module_id
    )
  ]
)

bootstrap_keys_unique <- !anyDuplicated(
  bootstrap_manifest[
    ,
    .(
      analysis_id,
      final_module_id
    )
  ]
)

all_reference_counts_match <- all(
  effect_results$
    bacterial_n_matches_reference
) &&
  all(
    effect_results$
      viral_n_matches_reference
  )

all_reference_summaries_match <- all(
  effect_results$
    mean_bacterial_abs_difference <=
    comparison_tolerance
) &&
  all(
    effect_results$
      mean_viral_abs_difference <=
      comparison_tolerance
  ) &&
  all(
    effect_results$
      mean_difference_abs_difference <=
      comparison_tolerance
  ) &&
  all(
    effect_results$
      median_bacterial_abs_difference <=
      comparison_tolerance
  ) &&
  all(
    effect_results$
      median_viral_abs_difference <=
      comparison_tolerance
  ) &&
  all(
    effect_results$
      median_difference_abs_difference <=
      comparison_tolerance
  )

all_reference_statistics_match <- all(
  effect_results$
    wilcoxon_u_abs_difference <=
    comparison_tolerance
) &&
  all(
    effect_results$
      rank_biserial_abs_difference <=
      comparison_tolerance
  ) &&
  all(
    effect_results$
      wilcoxon_p_abs_difference <=
      comparison_tolerance
  ) &&
  all(
    effect_results$
      wilcoxon_q_abs_difference <=
      comparison_tolerance
  )

all_reference_labels_match <- all(
  effect_results$
    observed_direction_matches_reference
) &&
  all(
    effect_results$
      direction_retained_matches_reference
  ) &&
  all(
    effect_results$
      nominal_significance_matches_reference
  ) &&
  all(
    effect_results$
      fdr_significance_matches_reference
  )

all_bootstraps_complete <- all(
  effect_results$
    bootstrap_replicates_completed ==
    bootstrap_replicates
) &&
  all(
    bootstrap_manifest$
      completed_replicates ==
      bootstrap_replicates
  )

all_intervals_finite <- all(
  is.finite(
    effect_results$
      hodges_lehmann_ci_low
  )
) &&
  all(
    is.finite(
      effect_results$
        hodges_lehmann_ci_high
    )
  ) &&
  all(
    is.finite(
      effect_results$
        rank_biserial_ci_low
    )
  ) &&
  all(
    is.finite(
      effect_results$
        rank_biserial_ci_high
    )
  )

all_interval_order_valid <- all(
  effect_results$
    hodges_lehmann_ci_low <=
    effect_results$
      hodges_lehmann_ci_high
) &&
  all(
    effect_results$
      rank_biserial_ci_low <=
    effect_results$
      rank_biserial_ci_high
  )

all_rank_biserial_bounds_valid <- all(
  effect_results$
    rank_biserial_effect >=
    -1
) &&
  all(
    effect_results$
      rank_biserial_effect <=
      1
  ) &&
  all(
    effect_results$
      rank_biserial_ci_low >=
      -1
  ) &&
  all(
    effect_results$
      rank_biserial_ci_high <=
      1
  )

all_seeds_unique <- (
  uniqueN(
    bootstrap_manifest$
      bootstrap_seed
  ) ==
    expected_effect_rows
)

quality_checks <- data.table(
  check_id = sprintf(
    "Q%02d",
    seq_len(18L)
  ),
  check_description = c(
    "Locked Script 47 projection quality summary validates",
    "Module-score input contains 1,715 rows",
    "Module-score keys are unique and finite",
    "Analysis manifest contains four locked analyses",
    "Reference test input contains 20 unique rows",
    "Coverage input contains five eligible frozen modules",
    "Twenty effect-size rows were generated",
    "Five primary manuscript-table rows were generated",
    "Twenty bootstrap-manifest rows were generated",
    "Effect-size keys are unique",
    "Bootstrap-manifest keys and seeds are unique",
    "All group counts match Script 47",
    "All recomputed group summaries match Script 47",
    "All recomputed test statistics and adjusted P values match Script 47",
    "All direction and significance labels match Script 47",
    "All 10,000 bootstrap replicates completed for every row",
    "All confidence intervals are finite and correctly ordered",
    "All rank-biserial estimates and intervals remain within minus one and one"
  ),
  pass = c(
    projection_quality_valid,
    nrow(scores) ==
      expected_score_rows,
    !anyDuplicated(
      scores[
        ,
        .(
          scoring_representation,
          geo_accession,
          final_module_id
        )
      ]
    ) &&
      !anyNA(scores$module_score) &&
      all(
        is.finite(scores$module_score)
      ),
    nrow(analysis_manifest) ==
      expected_manifest_rows &&
      identical(
        analysis_manifest$
          analysis_id,
        expected_analysis_ids
      ),
    nrow(reference_tests) ==
      expected_reference_test_rows &&
      !anyDuplicated(
        reference_tests[
          ,
          .(
            analysis_id,
            final_module_id
          )
        ]
      ),
    nrow(coverage) ==
      expected_coverage_rows &&
      all(
        coverage$coverage_fraction >=
          0.70
      ) &&
      all(
        coverage$
          representative_probes_frozen
      ),
    nrow(effect_results) ==
      expected_effect_rows,
    nrow(primary_table) ==
      expected_primary_rows,
    nrow(bootstrap_manifest) ==
      expected_effect_rows,
    effect_keys_unique,
    bootstrap_keys_unique &&
      all_seeds_unique,
    all_reference_counts_match,
    all_reference_summaries_match,
    all_reference_statistics_match,
    all_reference_labels_match,
    all_bootstraps_complete,
    all_intervals_finite &&
      all_interval_order_valid,
    all_rank_biserial_bounds_valid
  )
)

quality_gate_pass <- all(
  quality_checks$pass
)

quality_summary <- data.table(
  total_checks =
    nrow(quality_checks),
  passed_checks =
    sum(quality_checks$pass),
  failed_checks =
    sum(!quality_checks$pass),
  effect_size_rows =
    nrow(effect_results),
  primary_table_rows =
    nrow(primary_table),
  bootstrap_manifest_rows =
    nrow(bootstrap_manifest),
  bootstrap_replicates_per_row =
    bootstrap_replicates,
  total_bootstrap_replicates =
    sum(
      bootstrap_manifest$
        completed_replicates
    ),
  direction_retained_rows =
    sum(
      effect_results$
        direction_retained
    ),
  nominally_significant_rows =
    sum(
      effect_results$
        nominal_significant
    ),
  fdr_significant_rows =
    sum(
      effect_results$
        fdr_significant
    ),
  hodges_lehmann_ci_excluding_zero_rows =
    sum(
      effect_results$
        hodges_lehmann_ci_excludes_zero
    ),
  rank_biserial_ci_excluding_zero_rows =
    sum(
      effect_results$
        rank_biserial_ci_excludes_zero
    ),
  quality_gate =
    ifelse(
      quality_gate_pass,
      "PASS",
      "REVIEW"
    ),
  analysis_status =
    ifelse(
      quality_gate_pass,
      "READY_FOR_GSE72810_FIGURE_AND_MANUSCRIPT_INTEGRATION",
      "EFFECT_SIZE_ANALYSIS_REVIEW_REQUIRED"
    )
)


